import sys
import copy
import math
isIo = False
sys.setrecursionlimit(10 ** 6)
if isIo:
	sys.stdin = open('input.txt', 'r')
	sys.stdout = open('output.txt', 'w')
isTakeTestCase = True

def scanIntList():
	return map(int, input().split())

def printList(lst):
	for elem in lst:
		print(elem, end=' ')
	print()

def markDistance(tree, isSpecial, dist, parentOfSpec, root, par, distanceFromRoot):
	dist[root] = distanceFromRoot + 1
	dep = int(10000000000.0)
	depSpec = -1
	if root in isSpecial:
		parentOfSpec[root] = root
		dep = 0
		depSpec = root
	for node in tree[root]:
		if par != node:
			(specNode, tempDep) = markDistance(tree, isSpecial, dist, parentOfSpec, node, root, distanceFromRoot + 1)
			if dep > tempDep:
				dep = tempDep
				depSpec = specNode
	parentOfSpec[root] = depSpec
	return (parentOfSpec[root], dep + 1)

def dfs(tree, dist, parentOfSpec, objective, myspec, root, par, specAnc):
	if parentOfSpec[root] != -1:
		objective[root] = dist[root]
		specAnc = root
		myspec[root] = parentOfSpec[root]
	else:
		objective[root] = 2 * dist[specAnc] - dist[root]
		myspec[root] = parentOfSpec[specAnc]
	for node in tree[root]:
		if par != node:
			dfs(tree, dist, parentOfSpec, objective, myspec, node, root, specAnc)

def solve():
	(n, k, a) = scanIntList()
	special = list(scanIntList())
	isSpecial = {}
	for node in special:
		isSpecial[node] = True
	tree = [[] for _ in range(n + 1)]
	dist = [-1 for _ in range(n + 1)]
	objective = [-1 for _ in range(n + 1)]
	parentOfSpec = [0 for _ in range(n + 1)]
	myspec = [-1 for _ in range(n + 1)]
	for _ in range(n - 1):
		(x, y) = scanIntList()
		tree[x].append(y)
		tree[y].append(x)
	markDistance(tree, isSpecial, dist, parentOfSpec, a, -1, -1)
	dfs(tree, dist, parentOfSpec, objective, myspec, a, -1, -1)
	for i in range(1, n + 1):
		print(objective[i], end=' ')
	print()
	for i in range(1, n + 1):
		print(myspec[i], end=' ')
	print()

def driver():
	testCases = 1
	if isTakeTestCase:
		testCases = int(input())
	for i in range(testCases):
		solve()
driver()
